// ─── File: api/AccountApi.ts ───  (WHY api: fast preconditions + verify)
import { APIRequestContext } from '@playwright/test';
export class AccountApi {
  constructor(private request: APIRequestContext) {}
  async seed(id: string, balance: string) {
    const r = await this.request.post('/api/v1/accounts', { data: { id, balance } });
    if (!r.ok()) throw new Error('seed failed ' + r.status());
  }
  async balance(id: string): Promise<string> {
    return (await (await this.request.get(`/api/v1/accounts/${id}/balance`)).json()).balance;
  }
}
