// ─── File: pages/TransferPage.ts ───  (WHY pages: locators+actions once)
import { Page } from '@playwright/test';
export class TransferPage {
  constructor(private page: Page) {}
  async goto() { await this.page.goto('/transfer'); }
  async makeTransfer(from: string, to: string, amount: string) {
    await this.page.getByLabel('From account').selectOption(from);
    await this.page.getByLabel('To account').fill(to);
    await this.page.getByLabel('Amount').fill(amount);
    await this.page.getByRole('button', { name: 'Transfer' }).click();
  }
}
